function DeleteConfirmation(n,t,i){Swal.fire({title:globalconst.deleteConfirmMsg,text:globalconst.deleteConscentMsg,icon:"warning",showCancelButton:!0,cancelButtonText:globalconst.cancelBtnTitle,confirmButtonText:globalconst.cancelBtnInnerText}).then(function(r){if(r.value){let r="/"+t+"/Delete?Id="+n;$.ajax({type:"POST",url:r,contentType:"application/json; charset=utf-8",success:function(){Swal.fire({position:"top-right",icon:"success",title:""+i+" "+globalconst.deleteSuccessMsg,showConfirmButton:!1});setTimeout(function(){window.location.reload()},1500)}})}})}function DeleteConfirmationWithTypeDelete(n,t,i){Swal.fire({title:globalconst.deleteConfirmMsg,text:globalconst.deleteConscentMsg,icon:"warning",showCancelButton:!0,cancelButtonText:globalconst.cancelBtnTitle,confirmButtonText:globalconst.cancelBtnInnerText}).then(function(r){if(r.value){let r="/"+t+"/Delete?Id="+n;$.ajax({type:"DELETE",url:r,contentType:"application/json; charset=utf-8",success:function(){Swal.fire({position:"top-right",icon:"success",title:""+i+" "+globalconst.deleteSuccessMsg,showConfirmButton:!1});setTimeout(function(){window.location.reload()},1500)}})}})}